CREATE TABLE food (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(300) NOT NULL, category VARCHAR(100) NOT NULL,
 calories DOUBLE PRECISION NOT NULL CHECK(calories>=0), protein DOUBLE PRECISION NOT NULL CHECK(protein>=0), carbs DOUBLE PRECISION NOT NULL CHECK(carbs>=0), fat DOUBLE PRECISION NOT NULL CHECK(fat>=0),
 fiber DOUBLE PRECISION, sugar DOUBLE PRECISION, sodium DOUBLE PRECISION, serving_grams DOUBLE PRECISION NOT NULL DEFAULT 100,
 source VARCHAR(200) NOT NULL, source_id VARCHAR(64), owner_id UUID REFERENCES app_user(id) ON DELETE CASCADE);
CREATE INDEX food_search_idx ON food(lower(name)); CREATE INDEX food_category_idx ON food(category); CREATE INDEX food_owner_idx ON food(owner_id);
CREATE TABLE daily_target (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, date DATE NOT NULL,
 calories DOUBLE PRECISION NOT NULL, protein DOUBLE PRECISION NOT NULL, carbs DOUBLE PRECISION NOT NULL, fat DOUBLE PRECISION NOT NULL, fiber DOUBLE PRECISION NOT NULL, water INT NOT NULL, UNIQUE(user_id,date));
CREATE TABLE meal (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,date DATE NOT NULL,meal_type VARCHAR(16) NOT NULL CHECK(meal_type IN ('BREAKFAST','LUNCH','DINNER','SNACKS')),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(),copied_from UUID REFERENCES meal(id) ON DELETE SET NULL, UNIQUE(user_id,date,copied_from));
CREATE INDEX meal_user_date_idx ON meal(user_id,date);
CREATE TABLE meal_item (id UUID PRIMARY KEY,meal_id UUID NOT NULL REFERENCES meal(id) ON DELETE CASCADE,food_id BIGINT NOT NULL REFERENCES food(id),name VARCHAR(300) NOT NULL,
 grams DOUBLE PRECISION NOT NULL CHECK(grams BETWEEN 1 AND 2000),calories DOUBLE PRECISION NOT NULL,protein DOUBLE PRECISION NOT NULL,carbs DOUBLE PRECISION NOT NULL,fat DOUBLE PRECISION NOT NULL,fiber DOUBLE PRECISION NOT NULL,sugar DOUBLE PRECISION NOT NULL,sodium DOUBLE PRECISION NOT NULL,incomplete BOOLEAN NOT NULL DEFAULT false);
CREATE INDEX meal_item_meal_idx ON meal_item(meal_id);
CREATE TABLE water_entry (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,date DATE NOT NULL,ml INT NOT NULL CHECK(ml BETWEEN 1 AND 3000));
CREATE INDEX water_user_date_idx ON water_entry(user_id,date);
CREATE TABLE weight_entry (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,date DATE NOT NULL,kg DOUBLE PRECISION NOT NULL CHECK(kg BETWEEN 30 AND 350),UNIQUE(user_id,date));
CREATE INDEX weight_user_date_idx ON weight_entry(user_id,date);
CREATE TABLE activity_entry (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,date DATE NOT NULL,steps INT NOT NULL CHECK(steps BETWEEN 0 AND 100000),minutes INT NOT NULL CHECK(minutes BETWEEN 0 AND 600),UNIQUE(user_id,date));
CREATE INDEX activity_user_date_idx ON activity_entry(user_id,date);
CREATE TABLE favorite_food (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,food_id BIGINT NOT NULL REFERENCES food(id),UNIQUE(user_id,food_id));
CREATE TABLE saved_meal (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,meal_type VARCHAR(16) NOT NULL,items TEXT NOT NULL,planned_date DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX saved_meal_user_idx ON saved_meal(user_id);
